public static <T> T createInstance(Class<T> clazz) throws Exception {
    try {
        return clazz.getDeclaredConstructor().newInstance();
    } catch (NoSuchMethodException e) {
        // If no default constructor, try to find any constructor and use it
        Constructor<?>[] constructors = clazz.getDeclaredConstructors();
        if (constructors.length == 0) {
            throw new IllegalStateException("No constructors found for class: " + clazz.getName());
        }

        // Use the first constructor found (you might want to add more sophisticated logic here)
        Constructor<?> constructor = constructors[0];
        constructor.setAccessible(true);

        // Create default values for parameters
        Class<?>[] parameterTypes = constructor.getParameterTypes();
        Object[] arguments = new Object[parameterTypes.length];
        for (int i = 0; i < parameterTypes.length; i++) {
            arguments[i] = getDefaultValue(parameterTypes[i]);
        }

        return clazz.cast(constructor.newInstance(arguments));
    }
}

private static Object getDefaultValue(Class<?> type) {
    if (type == boolean.class) return false;
    if (type == byte.class) return (byte) 0;
    if (type == short.class) return (short) 0;
    if (type == int.class) return 0;
    if (type == long.class) return 0L;
    if (type == float.class) return 0.0f;
    if (type == double.class) return 0.0d;
    if (type == char.class) return '\0';
    return null;
}
```

